[DataContractAttribute]
class HSMobileOpsBatchRequest
{
    DataAreaId    dataAreaId;
    ItemId        itemId;
    InventBatchId batchId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('ItemId')]
public ItemId parmItemId(ItemId _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('BatchId')]
public InventBatchId parmBatchId(InventBatchId _value = batchId)
{
    batchId = _value;
    return batchId;
}
